// ---------------- Phone (local) ----------------
function toLocalMobile(num10) {
  if (!/^08\d{8}$/.test(num10)) return num10;
  return num10.slice(0,3) + " " + num10.slice(3,6) + " " + num10.slice(6);
}
function formatIrishMobileLocal(phone) {
  if (!phone) return "";
  let p = String(phone).trim();
  p = p.replace(/[^\d+]/g, "");
  if (p.startsWith("00")) p = "+" + p.slice(2);
  if (p.startsWith("353") && !p.startsWith("+353")) p = "+" + p;
  if (p.startsWith("+353")) {
    let rest = p.slice(4);
    if (rest.startsWith("0")) rest = rest.slice(1);
    return toLocalMobile("0" + rest);
  }
  const d = p.replace(/[^\d]/g, "");
  if (/^08\d{8}$/.test(d)) return toLocalMobile(d);
  if (/^8\d{8}$/.test(d)) return toLocalMobile("0" + d);
  if (/^0\d{7,9}$/.test(d)) return d;
  if (/^353\d{8,9}$/.test(d)) {
    let rest = d.slice(3);
    if (rest.startsWith("0")) rest = rest.slice(1);
    return toLocalMobile("0" + rest);
  }
  return String(phone).trim();
}

// ---------------- Helpers ----------------
const WEEK_NAME_TO_NUM = { first:1, second:2, third:3, fourth:4, fifth:5 };
const NUM_TO_WEEK_NAME = ["First","Second","Third","Fourth","Fifth"];
const DAY_NAME_TO_JS   = { sunday:0, monday:1, tuesday:2, wednesday:3, thursday:4, friday:5, saturday:6 };
const JS_TO_DAY_NAME   = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

function parseWeek(value) {
  if (value == null) return null;
  const raw = String(value).trim().toLowerCase();
  const numMatch = raw.match(/\b([1-5])\b/);
  if (numMatch) return Number(numMatch[1]);
  const word = raw.replace(/week|wk|#|-/g, "").trim();
  if (WEEK_NAME_TO_NUM[word]) return WEEK_NAME_TO_NUM[word];
  return null;
}

function parseWeekday(value) {
  if (!value) return null;
  const raw = String(value).trim();
  const dayLower = raw.toLowerCase();
  if (DAY_NAME_TO_JS[dayLower] != null) return DAY_NAME_TO_JS[dayLower];
  const short = dayLower.slice(0,3);
  const MAP3 = { sun:0, mon:1, tue:2, wed:3, thu:4, fri:5, sat:6 };
  if (MAP3[short] != null) return MAP3[short];
  const parts = raw.split(/\s+/);
  const maybeDay = parts[parts.length - 1].toLowerCase();
  if (DAY_NAME_TO_JS[maybeDay] != null) return DAY_NAME_TO_JS[maybeDay];
  return null;
}

function deriveWeekAndDay(row) {
  const weekField =
    row["Week"] ?? row["Collection Week"] ?? row["collection_week"] ?? row["week"] ?? row["WEEK"];
  const dayField =
    row["Day"] ?? row["Collection Day"] ?? row["collection_day"] ?? row["day"] ?? row["DAY"];

  let weekNum = parseWeek(weekField);
  let jsDay   = parseWeekday(dayField);

  // Allow "First Tuesday" style in dayField to backfill both
  if ((weekNum == null || jsDay == null) && typeof dayField === "string") {
    const lower = dayField.toLowerCase();
    const wkWord = Object.keys(WEEK_NAME_TO_NUM).find(w => lower.startsWith(w));
    if (wkWord) weekNum = weekNum ?? WEEK_NAME_TO_NUM[wkWord];
    const dayWord = Object.keys(DAY_NAME_TO_JS).find(d => lower.includes(d));
    if (dayWord) jsDay = jsDay ?? DAY_NAME_TO_JS[dayWord];
  }

  let label = "";
  if (weekNum != null && jsDay != null) {
    label = `${NUM_TO_WEEK_NAME[weekNum - 1]} ${JS_TO_DAY_NAME[jsDay]}`;
  } else if (typeof dayField === "string") {
    label = dayField;
  }

  return { weekNum, jsDay, label };
}

