// Format Irish mobile numbers into local "08X XXX XXXX" style
function formatIrishMobileLocal(phone) {
  if (!phone) return "";

  let p = String(phone).trim();

  // keep digits and +
  p = p.replace(/[^\d+]/g, "");

  // normalize prefixes
  if (p.startsWith("00")) p = "+" + p.slice(2);
  if (p.startsWith("353") && !p.startsWith("+353")) p = "+" + p;

  // +353 -> local
  if (p.startsWith("+353")) {
    let rest = p.slice(4); // after +353
    if (rest.startsWith("0")) rest = rest.slice(1);
    return toLocalMobile("0" + rest);
  }

  const d = p.replace(/[^\d]/g, "");

  // 08XXXXXXXXX -> local
  if (/^08\d{8}$/.test(d)) return toLocalMobile(d);

  // 8XXXXXXXX -> add leading 0 then local
  if (/^8\d{8}$/.test(d)) return toLocalMobile("0" + d);

  // landlines etc -> leave as compact digits (no spaces)
  if (/^0\d{7,9}$/.test(d)) return d;

  // intl without plus (353...) -> convert
  if (/^353\d{8,9}$/.test(d)) {
    let rest = d.slice(3);
    if (rest.startsWith("0")) rest = rest.slice(1);
    return toLocalMobile("0" + rest);
  }

  return String(phone).trim();
}

function toLocalMobile(num10) {
  // expect 10-digit mobile starting 08
  if (!/^08\d{8}$/.test(num10)) return num10;
  return num10.slice(0,3) + " " + num10.slice(3,6) + " " + num10.slice(6);
}

// Normalise routing area_code from full eircode + optional city
// Examples:
//  "D12 C424" -> "D12"
//  "D12C424"  -> "D12"
//  "A94 V403" -> "A94"
//  "K78P123"  -> "K78"
//  city "Wicklow" -> "WICKLOW"
function normalizeAreaCode(eircode, city) {
  const raw = eircode || city;
  if (!raw) return "";
  let code = String(raw).trim().toUpperCase();
  code = code.replace(/[\s\-\.]/g, "");

  // Wicklow by city keyword
  if ((city || "").toUpperCase().includes("WICKLOW")) return "WICKLOW";

  // Dublin
  if (code.startsWith("DUBLIN")) code = code.replace("DUBLIN", "D");
  if (code.startsWith("D")) {
    if (code.startsWith("D6W")) return "D6W";
    const m = code.substring(0, 3).match(/^D(\d{1,2})/);
    if (m) return "D" + m[1].padStart(2, "0");
  }

  // A/K routing keys (A94F123 -> A94, K78P123 -> K78)
  if (code.length >= 3 && /^[AK]\d{2}/.test(code)) return code.substring(0, 3);

  return "";
}

