// One Code node that filters ALL inputs (subs + once-off sheet) for "tomorrow"
// Pattern comes from Get Pattern HTTP node (pattern_only=1&days_ahead=1)

const pattern = $('Get Pattern').first().json;

// Pattern: tomorrow
const week      = Number(pattern.week);      // 1..5
const weekday   = Number(pattern.weekday);   // 0..6
const dateStr   = pattern.date;              // "YYYY-MM-DD"
const label     = pattern.week_label;        // "Third Tuesday"

// Month of tomorrow (lowercase, e.g. "november")
let monthNameLower = "";
if (dateStr) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  monthNameLower = dt
    .toLocaleString("en-IE", { month: "long" })
    .toLowerCase();
}

// Area/province lists from pattern (for subs only)
const areaList = (pattern.area_codes || []).map(c => String(c).toUpperCase());
const provList = (pattern.province_codes || []).map(c => String(c).toUpperCase());
const areaSet  = new Set(areaList);
const provSet  = new Set(provList);

// --- Helper: normalize area code from Eircode / ZIP ---
function normalizeAreaCode(eircode) {
  if (!eircode) return "";
  let code = String(eircode).trim().toUpperCase();
  code = code.replace(/[\s\-\.]/g, "");

  // "DUBLIN 7" / "DUBLIN7"
  if (code.startsWith("DUBLIN")) {
    const n = code.slice(6).replace(/\D/g, "");
    if (n) return "D" + n.padStart(2, "0");
  }

  // Default: first 3 chars as routing key
  if (code.length >= 3) return code.slice(0, 3);
  return "";
}

const out = [];

for (const item of $input.all()) {
