    const cw = r.collection_week != null ? Number(r.collection_week) : null;
    const cd = r.collection_weekday_js != null ? Number(r.collection_weekday_js) : null;

    const monthOk = cmLower === monthNameLower;
    const weekOk  = cw != null && cw === week;
    const dayOk   = cd != null && cd === weekday;

    if (!monthOk || !weekOk || !dayOk) {
      continue;
    }

    // Map zip -> eircode
    const eircode = r.eircode || r.zip || r.Zip || "";

    // Derive area_code from eircode if missing
    let area_code = r.area_code || "";
    if (!area_code && eircode) {
      area_code = normalizeAreaCode(eircode);
    }
    const finalAreaCode = area_code || normalizeAreaCode(eircode);

    out.push({
      json: {
        email:        r.email        || "",
        first_name:   r.first_name   || "",
        last_name:    r.last_name    || "",
        address_1:    r.address_1    || "",
        address_2:    r.address_2    || "",
        city:         r.city         || "",
        province:     r.province     || "",
        eircode:      eircode,
        country:      r.country      || "Ireland",
        phone:        r.phone        || "",
        area_code:    finalAreaCode || "",
        collection_week:  week,
        collection_day:   label,
        collection_date:  dateStr,
        match_type:   "sheet"
      }
    });

    continue;
  }

  // =========================
  // SUBSCRIBER PATH (Recharge/Woo/etc.)
  // =========================
  const prov = (r.province  || "").toUpperCase();
  let area_code = (r.area_code || "").toUpperCase();

  const rawEir = r.eircode || r.zip || r.Zip || "";
  if (!area_code && rawEir) {
    area_code = normalizeAreaCode(rawEir);
  }

  let matched = false;
  let match_type = null;

  if (areaSet.has(area_code)) {
    matched = true;
    match_type = "eircode";
  } else if (provSet.has(prov)) {
    matched = true;
    match_type = "province";
  }

  if (matched) {
    const eircode = rawEir;
    const finalAreaCode = area_code || normalizeAreaCode(eircode);

    out.push({
      json: {
        email:        r.email        || "",
        first_name:   r.first_name   || "",
        last_name:    r.last_name    || "",
        address_1:    r.address_1    || "",
        address_2:    r.address_2    || "",
        city:         r.city         || "",
        province:     r.province     || "",
        eircode:      eircode,
        country:      r.country      || "Ireland",
        phone:        r.phone        || "",
        area_code:    finalAreaCode || "",
        collection_week:  week,
        collection_day:   label,
        collection_date:  dateStr,
        match_type
      }
    });
  }
}

return out;

// Transform Collection Data to SmartRoutes Orders Format with Batching Support

const API_KEY = '716a82af-0bd6-47ff-92fc-fae38d578f0a';
const VEHICLE_ID = '2741'; // Your vehicle ID

// ---------- Helpers ----------

// Calculate tomorrow's date
const today = new Date();
const tomorrow = new Date(today);
tomorrow.setDate(today.getDate() + 1);

const formatDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const tomorrowDate = formatDate(tomorrow);

// Normalise Irish Eircode-style values
function normalizeEircode(value) {
  if (!value) return '';
  let s = String(value).toUpperCase().trim();

  // Remove spaces & non-alphanumerics
  s = s.replace(/[^A-Z0-9]/g, '');

  if (s.length <= 3) return s;

  // Format as "XXX XXXX"
  return s.slice(0, 3) + ' ' + s.slice(3);
}

// ---------- Main Transform ----------

const collections = $input.all();
console.log(`Processing ${collections.length} collections for SmartRoutes`);

const orders = [];
let successCount = 0;
let errorCount = 0;
let zipcodeIssues = [];
let orderCounter = 1; // For unique order numbers

for (const collection of collections) {
  const data = collection.json;

  try {
    // Build full name from first_name and last_name
    const fullName = `${data.first_name || ''} ${data.last_name || ''}`.trim();

    // Base address fields
    const address1 = String(data.address_1 || '').trim();
    const address2 = String(data.address_2 || '').trim();
    const city = String(data.city || '').trim();
    const province = String(data.province || '').trim();
    const country = String(data.country || 'Ireland').trim();

    // Primary postcode source: EIRCODE
    const rawEircode =
      (data.eircode || data.zip || data.original_zip || '').toString();
    const eircode = normalizeEircode(rawEircode);

    // Build complete address string for pickup_address (SmartRoutes requirement)
    let pickupAddress = address1;
    if (address2) pickupAddress += `, ${address2}`;
    if (city) pickupAddress += `, ${city}`;
    if (province) pickupAddress += `, ${province}`;
    if (eircode) pickupAddress += `, ${eircode}`;
    if (country && country !== 'Ireland') pickupAddress += `, ${country}`;

    // Determine the source (default to 'google_sheets' if not provided)
    const source = data.source
      ? data.source.replace(/[^a-zA-Z0-9_\-]/g, '').toLowerCase()
      : 'google_sheets';

    // Clean phone number (remove spaces)
    const rawPhone = data.phone ? data.phone.toString() : '';
    const cleanPhone = rawPhone.replace(/\s/g, '');

    // Use last 4 digits of phone as customer ID (still needed for SmartRoutes API)
    const customerId =
      cleanPhone.length >= 4
        ? Number(cleanPhone.slice(-4))
        : Number(cleanPhone) || Math.floor(Math.random() * 10000);

    // Email
    const email = data.email || '';

    // --- Postcode logic ---

    // Start with Eircode as postcode if present
    let postcode = eircode;

    // If still empty, attempt extraction from address (fallback)
    if (!postcode) {
      const addressMatch = pickupAddress.match(/[A-Z]\d{1,2}\s*[A-Z0-9]*/i);
      if (addressMatch) {
        postcode = addressMatch[0].toUpperCase();
        console.log(`📮 Extracted postcode from address: ${postcode} for ${fullName}`);
      } else {
        // For Meath/Kildare routes, use a default based on province
        if (province) {
          const provinceUpper = province.toUpperCase();
          if (provinceUpper === 'MEATH' || provinceUpper === 'MH') {
            postcode = 'MEATH';
          } else if (provinceUpper === 'KILDARE' || provinceUpper === 'KE') {
            postcode = 'KILDARE';
          }
        }

        if (postcode) {
          console.log(
            `📮 Using province-based postcode: ${postcode} for ${fullName} (${province})`
          );
        } else {
          postcode = 'UNKNOWN';
          console.log(`⚠️  No postcode found for ${fullName} - using 'UNKNOWN'`);
        }
      }
    }

    // Log postcode information for debugging
    console.log(
      `📮 Postcode for ${fullName}: "${postcode}" (eircode: "${rawEircode}", province: "${province}")`
    );

    // Track postcode issues: no original postcode at all
    if (!rawEircode) {
      zipcodeIssues.push({
        name: fullName,
        email: data.email,
        source: source,
        address: pickupAddress,
        province: province,
        assigned_postcode: postcode,
      });
    }

    // Skip if missing essential data
    if (!fullName || !address1 || !cleanPhone) {
      console.log(
        `⚠️  Skipping incomplete record: ${fullName} - missing essential data`
      );
      errorCount++;
      continue;
    }

    // Generate unique order number with timestamp and counter
    const timestamp = Date.now();
    const orderNumber = `COLL-${tomorrowDate}-${orderCounter}-${timestamp}`;
    orderCounter++;

    // Create SmartRoutes order
    const order = {
      order_number: orderNumber,
      type: 'pickup', // Collection = pickup in SmartRoutes

      // Customer object
      customer: {
        id: customerId,
        account: `CUST-${customerId}`,
        name: fullName,
        phone: cleanPhone,
        email: email,
        postcode: postcode,
        country_code: 'IE',
      },

      // Required delivery fields (even for pickup orders)
      delivery_address: pickupAddress,
      delivery_contact_name: fullName,
      delivery_contact_number: cleanPhone,
      delivery_contact_email: email,
      delivery_date: tomorrowDate,
      delivery_postcode: postcode,
      delivery_country_code: 'IE',

      // Pickup fields
      pickup_address: pickupAddress,
      pickup_contact_name: fullName,
      pickup_contact_number: cleanPhone,
      pickup_contact_email: email,
      pickup_date: tomorrowDate,
      pickup_postcode: postcode,
      pickup_country_code: 'IE',
      pickup_time_windows: [
        {
          from: '07:00',
          to: '20:00',
        },
      ],
      pickup_notes: `Glass collection - leave bag outside and accessible. Source: ${source}. Postcode: ${postcode}`,

      // Assign to your vehicle
      vehicle_id: VEHICLE_ID,
    };

    orders.push(order);
    successCount++;

    console.log(
      `✅ Processed: ${fullName} at ${pickupAddress} (Order: ${orderNumber}, Email: ${
        email || 'no-email'
      })`
    );
  } catch (error) {
    errorCount++;
    const name = `${data.first_name || ''} ${data.last_name || ''}`.trim() || 'Unknown';
    console.log(`❌ Error processing ${name}: ${error.message}`);
  }
}

// ---------- Batching ----------

const maxOrdersPerBatch = 100;
const totalOrders = orders.length;
const batches = [];

if (totalOrders <= maxOrdersPerBatch) {
  batches.push(orders);
} else {
  for (let i = 0; i < totalOrders; i += maxOrdersPerBatch) {
    batches.push(orders.slice(i, i + maxOrdersPerBatch));
  }
}

console.log(`\n📊 Transform Summary:`);
console.log(`   ✅ Successful: ${successCount}`);
console.log(`   ❌ Errors: ${errorCount}`);
console.log(`   📦 Total orders: ${totalOrders}`);
console.log(`   📋 Batches required: ${batches.length}`);
console.log(`   📅 Collection Date: ${tomorrowDate}`);
console.log(`   🚛 Vehicle ID: ${VEHICLE_ID}`);

if (zipcodeIssues.length > 0) {
  console.log(`\n📮 POSTCODE ISSUES SUMMARY:`);
  console.log(
    `Found ${zipcodeIssues.length} records with missing original postcodes/Eircodes:`
  );
  zipcodeIssues.forEach((issue) => {
    console.log(
      `   - ${issue.name} (${issue.email}) - Source: ${issue.source} - Assigned: ${issue.assigned_postcode}`
    );
  });
} else {
  console.log(`\n✅ All records had original postcodes/Eircodes`);
}

// ---------- Return payload ----------

const firstBatch = batches[0] || [];
const remainingBatches = batches.slice(1);

return [
  {
    json: {
      orders: firstBatch,
      metadata: {
        collection_date: tomorrowDate,
        total_orders: totalOrders,
        total_processed: orders.length,
        duplicates_removed: 0,
        batches_required: batches.length,
        current_batch: 1,
        remaining_batches: remainingBatches.length,
        vehicle_id: VEHICLE_ID,
        api_key: API_KEY,
        success_count: successCount,
        error_count: errorCount,
        zipcode_issues_count: zipcodeIssues.length,
      },
      remaining_batches: remainingBatches,
    },
  },
];

// Process SmartRoutes response and prepare optimization payload
const allInputItems = $input.all();
let createdOrders = [];
let errors = [];

for (const item of allInputItems) {
  const json = item.json;
  if (json.orders) {
    createdOrders.push(...(json.orders || []));
    errors.push(...(json.errors || []));
  }
}

// Get metadata from Transform node
const transformData = $('Transform to SmartRoutes Format').first().json;
const apiKey = transformData.metadata?.api_key;
const collectionDate = transformData.metadata?.collection_date;
const orderIds = createdOrders.map(order => parseInt(order.id));

console.log(`✅ ${orderIds.length} orders created. Preparing optimization.`);

return [{
  json: {
    order_ids: orderIds,
    collection_date: collectionDate,
    metadata: { api_key: apiKey, collection_date: collectionDate }
  }
}];

// Process optimization response + check readiness (merged If Ready check)
const optimizeResponse = $input.first();
const payloadData = $('Process Orders & Prepare Optimization').first().json;

let optimizationId = null;
let planId = null;

if (optimizeResponse.json && optimizeResponse.json.optimisation) {
    optimizationId = optimizeResponse.json.optimisation.id;
    planId = optimizeResponse.json.plan?.id;
    console.log(`Route Optimization Started`);
    console.log(`  Optimization ID: ${optimizationId}, Plan ID: ${planId}`);
    console.log(`  Total Orders: ${payloadData.order_ids ? payloadData.order_ids.length : 0}`);
} else {
    console.log('Route optimization failed');
    console.log('Response:', JSON.stringify(optimizeResponse.json, null, 2));
}

const collectionDateStr = payloadData.collection_date || payloadData.metadata?.collection_date;
let notificationTimeUTC = null;

if (collectionDateStr) {
    const collectionDate = new Date(collectionDateStr);
    const notificationDate = new Date(collectionDate);
    notificationDate.setDate(collectionDate.getDate() - 1);
    notificationDate.setHours(18, 30, 0, 0);
    notificationTimeUTC = notificationDate.toISOString().replace('T', ' ').substring(0, 19);
}

const ready = (payloadData.order_ids && payloadData.order_ids.length > 0 && optimizationId != null);

if (!ready) {
    console.log('Not ready for notifications — stopping pipeline');
    return [];
}

return [{
    json: {
        optimization_id: optimizationId,
        plan_id: planId,
        order_ids: payloadData.order_ids || [],
        collection_date: collectionDateStr,
        notification_time_utc: notificationTimeUTC,
        metadata: {
            ...payloadData.metadata,
            total_orders_final: payloadData.order_ids ? payloadData.order_ids.length : 0,
        }
    }
}];

// Prepare Notifications for SmartRoutes (SMS + Email) + readiness check
const notificationData = $('Process Optimization Response').first().json;

const smsTemplateId = 86;
const emailTemplateId = 1437;

const orderIds = notificationData.order_ids || [];
const sendTimeUtc = notificationData.notification_time_utc;

const ready = orderIds.length > 0 && !!sendTimeUtc;

if (!ready) {
    console.log('Not ready to schedule notifications — stopping pipeline');
    return [];
}

const smsRequest = {
  orders: orderIds,
  templates: [smsTemplateId],
  send_time_utc: sendTimeUtc,
};

const emailRequest = {
  orders: orderIds,
  templates: [emailTemplateId],
  send_time_utc: sendTimeUtc,
};

return [{
  json: {
    sms_notification_request: smsRequest,
    email_notification_request: emailRequest,
    template_ids: { sms: smsTemplateId, email: emailTemplateId },
    metadata: notificationData.metadata,
    summary: {
      collection_date: notificationData.collection_date,
      notification_time: sendTimeUtc,
      orders_count: orderIds.length,
    }
  }
}];

// Aggregate notification results + build HTML summary email
const prep = $('Prepare Notifications').first().json;
const smsResp = $('Schedule SMS Notifications').first().json || {};
const emailResp = $('Schedule Email Notifications').first().json || {};

const smsNotifs = Array.isArray(smsResp.notifications) ? smsResp.notifications : [];
const smsErrors = Array.isArray(smsResp.errors) ? smsResp.errors : [];
const emailNotifs = Array.isArray(emailResp.notifications) ? emailResp.notifications : [];
const emailErrors = Array.isArray(emailResp.errors) ? emailResp.errors : [];

const smsTemplateId = prep.template_ids?.sms ?? 86;
const emailTemplateId = prep.template_ids?.email ?? 1437;

const collectionDate = prep.summary.collection_date || "unknown-date";
const notifyTime = prep.summary.notification_time || "unknown-time";
const ordersTotal = prep.summary.orders_count ?? 0;

const nextSteps = [
  "Collection orders created in SmartRoutes",
  "Routes optimized for tomorrow",
  smsNotifs.length > 0 ? smsNotifs.length + " SMS notifications scheduled" : "Check SMS template/config",
  emailNotifs.length > 0 ? emailNotifs.length + " email notifications scheduled" : "Check email template/config",
  "Collection route ready in SmartRoutes dashboard",
];

const subject = `GlassBag \u2013 SmartRoutes Summary \u2013 ${collectionDate}`;

const html = `
<div style="font-family: Arial, sans-serif; max-width: 720px; margin: 0 auto; color: #111; line-height: 1.4;">
  <h2 style="margin: 0 0 12px;">SmartRoutes Daily Summary</h2>
  <table style="width: 100%; border-collapse: collapse; margin: 10px 0 18px;">
    <tr><td style="padding: 8px 10px; border: 1px solid #ddd; width: 40%; background: #fafafa;">Collection date</td><td style="padding: 8px 10px; border: 1px solid #ddd;">${collectionDate}</td></tr>
    <tr><td style="padding: 8px 10px; border: 1px solid #ddd; background: #fafafa;">Notification time (UTC)</td><td style="padding: 8px 10px; border: 1px solid #ddd;">${notifyTime}</td></tr>
    <tr><td style="padding: 8px 10px; border: 1px solid #ddd; background: #fafafa;">Orders processed</td><td style="padding: 8px 10px; border: 1px solid #ddd;">${ordersTotal}</td></tr>
  </table>
  <h3 style="margin: 0 0 10px;">Notifications</h3>
  <table style="width: 100%; border-collapse: collapse; margin: 10px 0 18px;">
    <tr><th style="text-align:left; padding: 8px 10px; border: 1px solid #ddd; background: #f3f3f3;">Channel</th><th style="text-align:right; padding: 8px 10px; border: 1px solid #ddd; background: #f3f3f3;">Scheduled</th><th style="text-align:right; padding: 8px 10px; border: 1px solid #ddd; background: #f3f3f3;">Errors</th></tr>
    <tr><td style="padding: 8px 10px; border: 1px solid #ddd;">SMS</td><td style="text-align:right; padding: 8px 10px; border: 1px solid #ddd;">${smsNotifs.length}</td><td style="text-align:right; padding: 8px 10px; border: 1px solid #ddd;">${smsErrors.length}</td></tr>
    <tr><td style="padding: 8px 10px; border: 1px solid #ddd;">Email</td><td style="text-align:right; padding: 8px 10px; border: 1px solid #ddd;">${emailNotifs.length}</td><td style="text-align:right; padding: 8px 10px; border: 1px solid #ddd;">${emailErrors.length}</td></tr>
  </table>
  <h3 style="margin: 0 0 10px;">Next steps</h3>
  <ul style="margin: 0; padding-left: 18px;">
    ${nextSteps.map(x => '<li style="margin: 4px 0;">' + String(x) + '</li>').join("")}
  </ul>
  <p style="margin: 18px 0 0; color: #444;">CSV attached: tomorrow's collections export.</p>
</div>`;

return [{
  json: {
    status: "completed",
    collection_date: collectionDate,
    notification_time: notifyTime,
    orders: { total_processed: ordersTotal, created_successfully: ordersTotal },
    notifications: {
      sms: { template_id: smsTemplateId, scheduled: smsNotifs.length, errors: smsErrors.length },
      email: { template_id: emailTemplateId, scheduled: emailNotifs.length, errors: emailErrors.length },
    },
    next_steps: nextSteps,
    email_subject: subject,
    email_body_html: html,
  }
}];
